import * as path from 'path';

export function resolveUserPath(root: string, userPath: string): string {
  return path.join(root, userPath);
}

initialFiles.src/files.test.ts:
import { resolveUserPath } from './files';

describe('resolveUserPath', () => {
  it('joins a name under the root', () => {
    const resolved = resolveUserPath('data', 'notes.txt');
    expect(resolved.endsWith('notes.txt')).toBe(true);
  });
});
